-- seed.sql — demo data for local development and a first look.
-- Runs after the migrations (supabase db reset). Products, prices and stock
-- are examples: replace them in Admin before going live. The logo and the
-- product illustrations are served from /public (brand/ and demo/).
-- Contact details are deliberately left empty.

insert into public.store_settings (id, store_name, tagline, logo_path, cod_terms, return_policy_days, order_ref_prefix, theme)
values (
  1, 'Sidraa', 'Premium for you', '/brand/logo-light.png',
  'Pay the rider in cash when your parcel arrives. You may check the items before paying. If something is wrong, refuse the parcel or contact us within the return window.',
  3, 'SD',
  '{"primary": "#e30363", "accent": "#ff7aa8"}'::jsonb
)
on conflict (id) do update
  set store_name = excluded.store_name, tagline = excluded.tagline, logo_path = excluded.logo_path, cod_terms = excluded.cod_terms,
      return_policy_days = excluded.return_policy_days, order_ref_prefix = excluded.order_ref_prefix, theme = excluded.theme;

